async def act(page):
    """Scroll to the bottom of the current page and navigate to page 3 of the blog feed.

    Steps:
    - Best-effort dismiss any blocking overlay by scanning role="button" elements for close-like labels or glyphs.
    - Scroll to the bottom to reveal pagination controls.
    - Prefer a deterministic href match: click the first link whose href contains 'paged=3' (final action).
    - Fallbacks: click a link named "Older posts" (page-wide) or a link whose visible text suggests page 3.

    The final click that navigates away is the last action in this function.
    """

    # Knowledge-base helper functions review (utility for this task):
    # - compile_recent_posts_digest / extract_post_summaries / export_visible_posts_to_csv /
    #   export_recent_posts_to_markdown / create_weekly_newsletter_draft / create_weekly_newsletter:
    #   All of these helpers begin by navigating to the site root ('/'). Using any would
    #   unconditionally navigate away from the current page state (/?paged=2) and are focused
    #   on extracting content rather than performing a localized UI click. Therefore none are
    #   appropriate for this precise action (clicking a pagination link). We will not call them.

    # 1) Best-effort dismiss overlays/popups by scanning role="button" elements
    try:
        buttons = page.get_by_role("button")
        try:
            btn_count = await buttons.count()
        except Exception:
            btn_count = 0

        close_tokens = ["close", "dismiss", "cancel", "ok", "done"]
        close_symbols = ["×", "✕", "✖", "x"]

        for i in range(btn_count):
            try:
                aria = await buttons.nth(i).get_attribute("aria-label") or ""
            except Exception:
                aria = ""
            try:
                title = await buttons.nth(i).get_attribute("title") or ""
            except Exception:
                title = ""
            try:
                txt = (await buttons.nth(i).inner_text()) or ""
            except Exception:
                txt = ""
            label = (aria or title or txt).strip()
            low = label.lower()

            if any(tok in low for tok in close_tokens) or any(sym in label for sym in close_symbols):
                try:
                    await buttons.nth(i).click()
                except Exception:
                    try:
                        await buttons.nth(i).click(force=True)
                    except Exception:
                        # if even force click fails on this button, continue scanning
                        continue
                await page.wait_for_timeout(300)
                break
    except Exception:
        # best-effort only; do not abort if overlay dismissal fails
        pass

    # 2) Scroll to the bottom to reveal pagination controls
    try:
        await page.evaluate("() => { window.scrollTo(0, document.body.scrollHeight); }")
    except Exception:
        # ignore evaluate failures
        pass
    await page.wait_for_timeout(600)

    # 3) Prefer deterministic href match for page 3
    links = page.get_by_role("link")
    try:
        total_links = await links.count()
    except Exception:
        total_links = 0

    for i in range(total_links):
        try:
            href = await links.nth(i).get_attribute("href")
        except Exception:
            href = None
        if href and "paged=3" in href:
            target = links.nth(i)
            try:
                await target.scroll_into_view_if_needed()
            except Exception:
                pass
            try:
                # Final click: navigate to page 3
                await target.click()
            except Exception:
                try:
                    await target.click(force=True)
                except Exception as e:
                    raise RuntimeError(f"Failed to click the page-3 link (href={href}): {e}")
            return

    # 4) Fallback: try a link named "Older posts" (page-wide)
    try:
        older = page.get_by_role("link", name="Older posts")
        if await older.count() > 0:
            try:
                await older.first().scroll_into_view_if_needed()
            except Exception:
                pass
            try:
                await older.first().click()
            except Exception:
                try:
                    await older.first().click(force=True)
                except Exception as e:
                    raise RuntimeError(f"Failed to click 'Older posts' link: {e}")
            return
    except Exception:
        pass

    # 5) Final fallback: click a link whose visible text suggests page 3 (e.g., '3' or 'page 3')
    text_tokens = ["page 3", "page3", " 3 ", "\n3\n"]
    for i in range(total_links):
        try:
            txt = (await links.nth(i).inner_text()) or ""
        except Exception:
            txt = ""
        low = txt.lower().strip()
        if low == "3" or any(tok in low for tok in text_tokens) or "older" in low:
            target = links.nth(i)
            try:
                await target.scroll_into_view_if_needed()
            except Exception:
                pass
            try:
                await target.click()
            except Exception:
                try:
                    await target.click(force=True)
                except Exception as e:
                    raise RuntimeError(f"Failed to click fallback page-3 link (text='{txt}'): {e}")
            return

    # Nothing matched: explicit failure so caller sees the problem
    raise RuntimeError("Unable to find a link to page 3 (href containing 'paged=3' or link named 'Older posts' or visible text '3'/'page 3').")

